import FALLBACK_INPUTS from "./work-data";
import type { WorkMedia, WorkProject, WorkProjectInput } from "./work.types";
import { getYouTubeId, withSlugs } from "./work-utils";

const WORK_URL = "https://pinktra-work.netlify.app/works.json";
 
function isMedia(value: unknown): value is WorkMedia {
  const media = value as WorkMedia | null;
  if (!media || typeof media.url !== "string") return false;
  if (media.type === "image" || media.type === "video") return true;
  // A YouTube entry is only kept if we can actually extract a video id from it.
  return media.type === "youtube" && getYouTubeId(media.url) !== null;
}

/** Keeps only well-formed entries so one bad record can't break the page. */
function parseInputs(data: unknown): WorkProjectInput[] {
  if (!Array.isArray(data)) throw new Error("work.json is not an array");

  return data
    .filter(
      (item) =>
        item &&
        typeof item.title === "string" &&
        typeof item.category === "string" &&
        typeof item.cover === "string",
    )
    .map((item) => ({
      title: item.title,
      category: item.category,
      cover: item.cover,
      gallery: Array.isArray(item.gallery) ? item.gallery.filter(isMedia) : [],
      description: typeof item.description === "string" ? item.description : undefined,
      feedback:
        item.feedback && typeof item.feedback.quote === "string"
          ? { quote: item.feedback.quote, author: item.feedback.author }
          : undefined,
    }));
}

/**
 * Server-only. Fetched once at build time and cached ("force-cache"), with no
 * revalidation. To pick up changes to work.json, rebuild/redeploy.
 * Falls back to the bundled work-data.ts if the CDN is unreachable.
 */
export async function getProjects(): Promise<WorkProject[]> {
  try {
    const response = await fetch(WORK_URL, { cache: "force-cache" });
    if (!response.ok) throw new Error(`work.json responded ${response.status}`);
    return withSlugs(parseInputs(await response.json()));
  } catch (error) {
    console.error("Failed to load work.json, using bundled data:", error);
    return withSlugs(FALLBACK_INPUTS);
  }
}
